  overscroll-behavior: none;
}

body { touch-action: none; }

#stage {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #0d0a07;
}

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

.grain {
  position: absolute;
  inset: -40%;
  pointer-events: none;
  opacity: .14;
  z-index: 3;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.78' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.45'/%3E%3C/svg%3E");
  animation: grainShift .45s steps(2) infinite;
  mix-blend-mode: overlay;
}

@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}

.screen-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
  background:
    linear-gradient(180deg, rgba(10,7,4,.55) 0%, transparent 16%, transparent 72%, rgba(10,7,4,.58) 100%),
    radial-gradient(ellipse at center, transparent 52%, rgba(10,7,4,.58) 100%);
}

.is-hidden { display: none !important; }

button { font: inherit; color: inherit; }

/* ============================= TITLE ============================= */

.title-screen {
  position: absolute;
