  flex-direction: column;
  justify-content: space-between;
  padding: max(28px, env(safe-area-inset-top)) clamp(24px, 5.2vw, 82px) max(26px, env(safe-area-inset-bottom));
  background:
    linear-gradient(90deg, rgba(8,6,4,.86) 0%, rgba(8,6,4,.58) 31%, rgba(8,6,4,.06) 67%, transparent 100%),
    linear-gradient(0deg, rgba(8,6,4,.82) 0%, transparent 30%, transparent 78%, rgba(8,6,4,.35) 100%);
  transition: opacity .8s ease, visibility .8s;
}

.title-screen::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(25% - 1px), rgba(236,201,150,.05) calc(25% - 1px), rgba(236,201,150,.05) 25%);
  mask-image: linear-gradient(180deg, transparent, #000 20%, #000 80%, transparent);
