// ---------------------------------------------------------------------------
function startGame(continueRun = false) {
  Audio.resume();
  mode = 'playing';
  paused = false;
  panelOpen = false;
  effects = [];
  particles = [];
  if (continueRun) {
    if (!loadGame()) {
      state = freshState();
      camera.x = state.player.x; camera.y = state.player.y;
    }
