  ctx.strokeStyle = 'rgba(232,184,125,.14)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  for (let x = 0; x <= w; x += 20) {
    const y = yBase + Math.sin(x * 0.004 + phase) * amp * 0.24 + Math.sin(x * 0.011 + phase * 2) * amp * 0.1;
    if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
