function saveGame(silent = true) {
  if (!state || mode !== 'playing') return;
  try {
    const data = {
      version: 1,
      player: { ...state.player },
      water: state.water, food: state.food, health: state.health,
      credits: state.credits, scrap: state.scrap, relics: state.relics,
